import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            s = next(iterator)
        except StopIteration:
            break

        w_index = s.find('W')

        # Count black cells on the left
        left_count = 0
        for i in range(w_index):
            if s[i] == 'B':
                left_count += 1

        # Count black cells on the right
        right_count = 0
        for i in range(w_index + 1, len(s)):
            if s[i] == 'B':
                right_count += 1

        # Game theory logic:
        # This is equivalent to a Nim game with two piles of sizes left_count and right_count.
        # A move consists of removing k (>0) items from exactly one pile.
        # The player who faces a state where both piles are 0 loses.
        # In Nim, the first player wins if the XOR sum of pile sizes is non-zero.
        # Here, the piles are independent, so we check if left_count ^ right_count != 0.
        # If XOR is non-zero, the first player (Aleksa) has a winning strategy.
        # If XOR is zero, the second player (Chef) has a winning strategy.

        if (left_count ^ right_count) != 0:
            results.append("Aleksa")
        else:
            results.append("Chef")

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
